struct Bucket { std::atomic<int64_t> time{-1}; std::atomic<int> count{0}; };
Bucket b[300];

void hit(int64_t sec) {
  Bucket& x = b[sec % 300];
  if (x.time.load() != sec) {
    x.time.store(sec);
    x.count.store(0);
  }
  x.count.fetch_add(1);
}
